var C = ARISTO.colors;
var steepIn = document.getElementById('steep');
var tposIn = document.getElementById('tpos');
var tanBtn = document.getElementById('tanBtn');
var showTangent = false;

// Path: segment 1 from t=0..4, distance 0..40 (fixed, speed 10 m/s)
// segment 2 from t=4..10, slope = steepness (m/s), clamped so distance stays within 0..100
var T1 = 4, D1 = 40;
var TMAX = 10;

function seg2Slope() {
  return +steepIn.value;
}

function distAt(t) {
  if (t <= T1) return (D1 / T1) * t;
  var m = seg2Slope();
  var d = D1 + m * (t - T1);
  if (d < 0) d = 0;
  if (d > 100) d = 100;
  return d;
}

function speedAt(t) {
  if (t < T1) return D1 / T1;
  if (t > T1) {
    var m = seg2Slope();
    var d = D1 + m * (t - T1);
    if (d <= 0 || d >= 100) return 0;
    return m;
  }
  // exactly at the bend, report segment 2's speed as the "just after" value
  return seg2Slope();
}

function fmt1(n) { return (Math.round(n * 10) / 10).toString(); }

var dragging = false;

var plot = ARISTO.canvas(document.getElementById('plot'), function (ctx, w, h) {
  var padL = 46, padB = 32, padT = 14, padR = 14;
  var gw = w - padL - padR, gh = h - padT - padB;
  function X(t) { return padL + (t / TMAX) * gw; }
  function Y(d) { return padT + gh - (d / 100) * gh; }

  // grid
  ctx.strokeStyle = C.line; ctx.lineWidth = 1;
  for (var t = 0; t <= TMAX; t += 1) {
    ctx.beginPath(); ctx.moveTo(X(t), padT); ctx.lineTo(X(t), padT + gh); ctx.stroke();
  }
  for (var d = 0; d <= 100; d += 10) {
    ctx.beginPath(); ctx.moveTo(padL, Y(d)); ctx.lineTo(padL + gw, Y(d)); ctx.stroke();
  }

  // axes
  ctx.strokeStyle = C.muted; ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(padL, padT); ctx.lineTo(padL, padT + gh); ctx.lineTo(padL + gw, padT + gh); ctx.stroke();

  ctx.fillStyle = C.muted; ctx.font = '12px system-ui, sans-serif';
  ctx.textAlign = 'center';
  for (var t2 = 0; t2 <= TMAX; t2 += 2) {
    ctx.fillText(String(t2), X(t2), padT + gh + 16);
  }
  ctx.textAlign = 'right';
  for (var d2 = 0; d2 <= 100; d2 += 20) {
    ctx.fillText(String(d2), padL - 6, Y(d2) + 4);
  }
  ctx.textAlign = 'center';
  ctx.fillText('Time (s)', padL + gw / 2, h - 4);
  ctx.save();
  ctx.translate(12, padT + gh / 2);
  ctx.rotate(-Math.PI / 2);
  ctx.fillText('Distance (m)', 0, 0);
  ctx.restore();

  // path: segment 1
  ctx.strokeStyle = C.accentText; ctx.lineWidth = 3; ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(X(0), Y(0));
  ctx.lineTo(X(T1), Y(D1));
  ctx.stroke();

  // segment 2, clamped visually at 0 or 100
  var m = seg2Slope();
  var pts = [];
  var steps = 60;
  for (var i = 0; i <= steps; i++) {
    var tt = T1 + (TMAX - T1) * (i / steps);
    pts.push([tt, distAt(tt)]);
  }
  ctx.beginPath();
  ctx.moveTo(X(pts[0][0]), Y(pts[0][1]));
  for (var j = 1; j < pts.length; j++) ctx.lineTo(X(pts[j][0]), Y(pts[j][1]));
  ctx.stroke();

  // marker dot
  var tm = +tposIn.value;
  var dm = distAt(tm);
  var mx = X(tm), my = Y(dm);

  // tangent line
  if (showTangent) {
    var sp = speedAt(tm);
    var dt = 1.4;
    var t0 = tm - dt, t1b = tm + dt;
    var d0 = dm - sp * dt, d1 = dm + sp * dt;
    ctx.setLineDash([6, 4]); ctx.strokeStyle = C.info; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(X(t0), Y(d0)); ctx.lineTo(X(t1b), Y(d1)); ctx.stroke();
    ctx.setLineDash([]);
  }

  // dashed guides to axes
  ctx.setLineDash([4, 4]); ctx.strokeStyle = C.muted; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(mx, my); ctx.lineTo(mx, padT + gh); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(padL, my); ctx.lineTo(mx, my); ctx.stroke();
  ctx.setLineDash([]);

  ctx.fillStyle = C.accentText;
  ctx.beginPath(); ctx.arc(mx, my, 7, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = C.surface; ctx.lineWidth = 2; ctx.stroke();

  plot._X = X; plot._Y = Y; plot._padL = padL; plot._padT = padT; plot._gw = gw; plot._gh = gh;
}, 0.72);

function update() {
  var m = seg2Slope();
  document.getElementById('steepv').textContent = String(m);
  var tm = +tposIn.value;
  document.getElementById('tposv').textContent = fmt1(tm) + ' s';
  var dm = distAt(tm);
  var sp = speedAt(tm);
  document.getElementById('readout').textContent = 'At ' + fmt1(tm) + ' s: ' + fmt1(dm) + ' m, speed ' + fmt1(sp) + ' m/s';
  plot.redraw();
}

steepIn.addEventListener('input', update);
tposIn.addEventListener('input', update);
tanBtn.addEventListener('click', function () {
  showTangent = !showTangent;
  tanBtn.setAttribute('aria-pressed', String(showTangent));
  update();
});

// dragging on canvas
var canvasEl = document.getElementById('plot');

function posToTime(clientX, clientY) {
  var rect = canvasEl.getBoundingClientRect();
  var x = clientX - rect.left;
  var t = ((x - plot._padL) / plot._gw) * TMAX;
  if (t < 0) t = 0;
  if (t > TMAX) t = TMAX;
  return t;
}

function nearMarker(clientX, clientY) {
  var rect = canvasEl.getBoundingClientRect();
  var x = clientX - rect.left, y = clientY - rect.top;
  var tm = +tposIn.value;
  var mx = plot._X(tm), my = plot._Y(distAt(tm));
  var dx = x - mx, dy = y - my;
  return Math.sqrt(dx * dx + dy * dy) < 30;
}

canvasEl.style.touchAction = 'none';

canvasEl.addEventListener('pointerdown', function (e) {
  if (nearMarker(e.clientX, e.clientY)) {
    dragging = true;
    canvasEl.setPointerCapture(e.pointerId);
  }
});
canvasEl.addEventListener('pointermove', function (e) {
  if (!dragging) return;
  var t = posToTime(e.clientX, e.clientY);
  tposIn.value = String(Math.round(t * 10) / 10);
  update();
});
canvasEl.addEventListener('pointerup', function (e) { dragging = false; });
canvasEl.addEventListener('pointercancel', function (e) { dragging = false; });

update();
